 * The store is display state, doesn't do its own calculation, and doesn't
 * advance its own timer. Follows the subscribe/emit idiom of state/docked.ts
 * and state/cargo.ts: set → emit only on change (stable JSON comparison);
 * late subscribers can catch up. HUD only.
 */

import { canonicalJson } from '@shared/canonical';
import { EXPOSURE_MAX } from '@shared/world/hazards';

/** The wire shape of the 'hazard' frame (schemas.ts, server-originated). */
export interface HazardFrame {
  /** Personal exposure pool 0..50 (the server is the authority). */
  exposure: number;
  /** The hazard kind the player is standing in (omitted when out in the open). */
  inside?: 'storm' | 'radzone';
  /** Epoch-milliseconds end time of the 5-second knockdown (omitted when not in effect). */
  recoveringUntil?: number;
}

/** Hazard view the HUD renders. */
export interface HazardState {
  exposure: number;
  inside: 'storm' | 'radzone' | null;
  /** The 5-second 'SHIELD BURN' knockdown is in effect (deadline is still in the future). */
  recovering: boolean;
}

type HazardListener = (state: HazardState) => void;

const CLEAR: HazardState = { exposure: EXPOSURE_MAX, inside: null, recovering: false };

const listeners = new Set<HazardListener>();
let current: HazardState = CLEAR;
let currentJson = canonicalJson(CLEAR);

function emit(next: HazardState): void {
  const json = canonicalJson(next);
  if (json === currentJson) return;
  current = next;
  currentJson = json;
  for (const fn of [...listeners]) fn(next);
}

